package com.shazwan.idash.a1lab;
import android.app.*;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.os.*;import android.view.*;import org.json.*;import java.io.*;import java.util.concurrent.*;
/** Disposable stock emulator only. Never grants a feature or installs a real music app. */
public final class A1Checks extends Instrumentation {
 ProbeHostActivity a;int checks;StringBuilder notes=new StringBuilder();volatile IBinder bridge;ServiceConnection connection;boolean bound;
 void check(boolean ok,String why){if(!ok)throw new AssertionError(why);checks++;}
 void ui(Runnable task){Throwable[] error={null};runOnMainSync(()->{try{task.run();}catch(Throwable e){error[0]=e;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 int call(int code)throws Exception{Parcel data=Parcel.obtain(),reply=Parcel.obtain();try{data.writeInterfaceToken(DashNativeFrame.TOKEN);bridge.transact(code,data,reply,0);reply.readException();return reply.readInt();}finally{data.recycle();reply.recycle();}}
 String memory(String at){Debug.MemoryInfo info=new Debug.MemoryInfo();Debug.getMemoryInfo(info);return at+" pss_kib="+info.getTotalPss()+" java_used="+(Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory())+" cpu_ms="+android.os.Process.getElapsedCpuTime();}
 View find(View root,String desc){if(desc.equals(root.getContentDescription()))return root;if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++){View v=find(group.getChildAt(i),desc);if(v!=null)return v;}}return null;}
 boolean full(View v){Rect visible=new Rect();return v!=null&&v.getGlobalVisibleRect(visible)&&visible.width()==v.getWidth()&&visible.height()==v.getHeight();}
 void photo(String name)throws Exception{Thread.sleep(600);waitForIdleSync();Bitmap shot=getUiAutomation().takeScreenshot();check(shot!=null,"actual screenshot");try(OutputStream out=new FileOutputStream(new File(a.getFilesDir(),name))){shot.compress(Bitmap.CompressFormat.PNG,100,out);}shot.recycle();}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;try{
  a=(ProbeHostActivity)startActivitySync(new Intent(getTargetContext(),ProbeHostActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));CountDownLatch ready=new CountDownLatch(1);a.worker.execute(()->a.main.post(ready::countDown));check(ready.await(60,TimeUnit.SECONDS),"background discovery/cache ready");waitForIdleSync();
  PackageManager pm=a.getPackageManager();String target="com.shazwan.idash.a1lab.target";check(!a.getPackageName().equals("com.shazwan.idash"),"stable package is not target of test");check(pm.getApplicationInfo(target,0).uid!=android.os.Process.myUid(),"separate host/target UID");check(pm.checkSignatures(a.getPackageName(),target)==PackageManager.SIGNATURE_MATCH,"lab signer matches");check(DashNativeFrame.declaredEmbedded(pm,DashNativeFrame.TARGETS[0]),"actual compiled manifest opt-in via public XML API");ServiceInfo service=pm.getServiceInfo(new ComponentName(target,target+".Bridge"),0);check(service.exported&&DashNativeFrame.CONTROL.equals(service.permission),"bridge signature permission declared");check(pm.checkPermission(DashNativeFrame.CONTROL,a.getPackageName())==PackageManager.PERMISSION_GRANTED,"host signature grant");
  connection=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){bridge=b;}public void onServiceDisconnected(ComponentName n){bridge=null;}};ui(()->bound=a.bindService(new Intent().setComponent(new ComponentName(target,target+".Bridge")),connection,Context.BIND_AUTO_CREATE));long end=SystemClock.elapsedRealtime()+15000;while(bridge==null&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);check(bound&&bridge!=null,"authorized cross-UID Binder connection");check(call(8)==1,"authenticated protocol handshake");check(call(3)==-1,"target Activity not launched by binding");ui(()->{a.unbindService(connection);bound=false;});
  DashNativeFrame frame=a.nativePanel;boolean feature=pm.hasSystemFeature("android.software.activities_on_secondary_displays");notes.append("api=").append(Build.VERSION.SDK_INT).append(" abi=").append(java.util.Arrays.toString(Build.SUPPORTED_ABIS)).append(" feature=").append(feature).append(" host_uid=").append(android.os.Process.myUid()).append(" target_uid=").append(pm.getApplicationInfo(target,0).uid).append('\n').append(memory("before")).append('\n');
  ui(()->{for(String desc:new String[]{"Clock widget","JAKIM calendar widget","Calendar widget"})check(full(find(a.stage,desc)),"left fully visible "+desc);check(a.clock.getWidth()<a.stage.getWidth()/2,"clock remains left");});
  String size=a.getResources().getDisplayMetrics().widthPixels+"x"+a.getResources().getDisplayMetrics().heightPixels;
  if(!feature){ui(()->{for(int n=0;n<20;n++){frame.start();check(!frame.wanted&&frame.display==null&&frame.remote==null&&frame.inputThread==null&&!frame.bound,"unsupported attempt releases everything "+n);frame.stop();}});notes.append("20 iterations are rejected start/stop attempts, NOT successful hosted open/close.\n");photo("a1-stock-"+size+"-capability-blocked.png");
   ui(frame::probeOwnDisplay);end=SystemClock.elapsedRealtime()+30000;while(frame.diagnosticActual==-1&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);check(frame.diagnosticActual!=-1,"own proxy diagnostic completed");notes.append("own_proxy_expected=").append(frame.diagnosticExpected).append(" actual=").append(frame.diagnosticActual).append(" status=").append(frame.status.getText()).append('\n');check(frame.display==null&&!frame.wanted,"diagnostic releases display");photo("a1-stock-"+size+"-own-display-result.png");
   result.putString("a1_gate","INCONCLUSIVE_STOCK_PLATFORM_UNAVAILABLE");notes.append("A1 cross-UID secondary-display rendering/touch/Back/resize/audio/realIME NOT TESTED. Own UID diagnostic is not A1 success. No BitChord fork started.\n");
  }else{ui(frame::start);end=SystemClock.elapsedRealtime()+65000;while(!frame.targetConfirmed&&frame.wanted&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);check(frame.targetConfirmed&&frame.lastObservedDisplay>0,"cross-UID target confirms secondary display");photo("a1-stock-"+size+"-native-target.png");result.putString("a1_gate","RENDERED_INTERACTION_TESTS_STILL_REQUIRED");ui(frame::stop);}
  notes.append(memory("after")).append('\n');Runtime.getRuntime().gc();Thread.sleep(500);notes.append(memory("after_gc_request")).append('\n');ui(()->{frame.stop();check(frame.display==null&&frame.inputThread==null&&!frame.bound,"final cleanup");for(String desc:new String[]{"Clock widget","JAKIM calendar widget","Calendar widget"})check(full(find(a.stage,desc)),"left retained after probes "+desc);});
  try(Writer out=new FileWriter(new File(a.getFilesDir(),"a1-stock-"+size+"-report.txt"))){out.write(notes.toString());}result.putString("stream","PASS: "+checks+" lab safety/capability checks\n"+notes);code=Activity.RESULT_OK;
 }catch(Throwable e){result.putString("stream","FAIL after "+checks+": "+e+"\n"+notes);}finally{if(a!=null)ui(()->{if(bound){a.unbindService(connection);bound=false;}if(a.nativePanel!=null)a.nativePanel.stop();a.finish();});}finish(code,result);}
}
